<?php
namespace App\Services;
use App\Models\{User,Task,Attendance,WeeklyConsolidatedItem,PerformanceRegister};
use Illuminate\Support\{Carbon,Collection};
use Illuminate\Support\Facades\Validator;
class BrandsDashboard {
 public function build(array $filters,User $actor):array {
  $v=Validator::make($filters,['tab'=>'nullable|in:productivity,people,perfect_store,activation,visibility,workstream','period'=>'nullable|in:week,month,year','date'=>'nullable|date_format:Y-m-d','owner'=>'nullable|integer|min:1','partner'=>'nullable|in:castel,unilever','q'=>'nullable|string|max:150','sort'=>'nullable|in:newest,oldest,title,owner','page'=>'nullable|integer|min:1','per_page'=>'nullable|integer|min:5|max:50'])->validate();
  $tab=$v['tab']??'productivity';$period=$v['period']??'week';$anchor=Carbon::parse($v['date']??today());
  $from=match($period){'month'=>$anchor->copy()->startOfMonth(),'year'=>$anchor->copy()->startOfYear(),default=>$anchor->copy()->startOfWeek()};$to=match($period){'month'=>$from->copy()->endOfMonth(),'year'=>$from->copy()->endOfYear(),default=>$from->copy()->endOfWeek()};
  $aliases=User::departmentAliases('brands_marketing');
  $weekly=WeeklyConsolidatedItem::with('leadStaff','creator')->whereIn('department',$aliases)->whereDate('week_start','<=',$to)->whereDate('week_end','>=',$from)->when($period!=='week',fn($q)=>$q->whereDate('week_start','>=',$from))->get();
  $registers=PerformanceRegister::whereIn('department',$aliases)->whereNotNull('approved_at')->whereDate('period_start','<=',$to)->whereDate('period_end','>=',$from)->when($period!=='week',fn($q)=>$q->whereDate('period_start','>=',$from))->get();
  $historyIds=$from->lt(now()->startOfWeek())?$weekly->pluck('lead_staff_id')->merge($weekly->pluck('created_by'))->merge($weekly->flatMap(fn($w)=>$w->supporting_staff_ids??[]))->merge($registers->pluck('owner_id')):collect();
  $staff=User::internalStaff()->whereIn('department',$aliases)->orderBy('name')->get()->filter(fn($u)=>$u->isActive()||($u->status==='suspended'&&$historyIds->contains($u->id)))->values();
  $names=User::internalStaff()->pluck('name','id');$owner=$v['owner']??null;
  $matches=function($row)use($v,$owner){return (!$owner||(int)$row['owner_id']===(int)$owner||in_array((int)$owner,array_map('intval',$row['data']['collaborators']??[]),true))&&(empty($v['q'])||str_contains(mb_strtolower(strip_tags($row['title'].' '.json_encode($row['data']))),mb_strtolower($v['q'])));};
  $reports=app(BrandsReports::class);$rows=$weekly->toBase()->map(fn($w)=>$reports->payload($w,'weekly')+['id'=>$w->id,'source_type'=>'weekly','source_token'=>BrandsReports::token($w),'source_label'=>$w->report_status==='reviewed'?'Reviewed report':'Saved weekly report'])->merge($registers->toBase()->filter(fn($r)=>isset(config('brands_dashboard.schemas')[$r->kind])||$r->kind==='campaign')->map(fn($r)=>$reports->payload($r,'register')+['id'=>$r->id,'source_type'=>'register','source_token'=>BrandsReports::token($r),'source_label'=>$r->kind==='campaign'?'Saved activity':'Reviewed report']))->filter($matches)->values();
  $rows=$rows->map(fn($row)=>$row+['owner'=>$names[$row['owner_id']]??'Retained staff history','can_edit'=>BrandsReports::member($actor)&&(BrandsReports::manager($actor)||(int)$row['owner_id']===$actor->id)]);
  $tables=[];$summary=[];$notice='';
  $col=fn($key,$label,$format='text')=>compact('key','label','format');
  $base=[$col('week','Reporting Week','date'),$col('title','Activity'),$col('owner','Owner')];
  $flatten=fn($r)=>array_merge($r,$r['data']);
  if($tab==='productivity'){
   $users=$owner?$staff->where('id',(int)$owner):$staff;
   $tasksQuery=Task::with('assignee')->realWork()->whereIn('department',$aliases)->where(fn($q)=>$q->whereBetween('created_at',[$from,$to])->orWhereBetween('due_on',[$from,$to])->orWhereBetween('completion_reviewed_at',[$from,$to]));
   if($owner)$tasksQuery->where('assigned_to',$owner);
   if(!empty($v['q']))$tasksQuery->where(fn($q)=>$q->where('title','like','%'.$v['q'].'%')->orWhere('client_name','like','%'.$v['q'].'%'));
   $tasks=$tasksQuery->get();$completed=$tasks->filter(fn($t)=>$t->isApprovedForPerformance())->count();
   $logs=Attendance::whereIn('user_id',$users->pluck('id'))->whereBetween('clock_in_at',[$from,$to])->get();
   $closed=$logs->whereNotNull('clock_out_at');$punctual=0;$expected=0;$scores=[];
   foreach($users as $u){$score=app(StaffPerformanceScore::class)->user($u,$from,$to);$punctual+=$score['punctual_days'];$expected+=$score['expected_workdays'];$scores[]=$score['score'];}
   $summary=[['Clock-in Hours',$closed->isEmpty()?null:round($closed->sum(fn($a)=>$a->scheduledWorkingMinutes()??0)/60,1),'hours'],['Tasks Assigned',$tasks->count(),'number'],['Tasks Completed',$completed,'number'],['Punctuality Score',$expected?round(100*$punctual/$expected,1):null,'percent'],['Completion Rate',$tasks->count()?round(100*$completed/$tasks->count(),1):null,'percent'],['Productivity Score',count($scores)&&!in_array(null,$scores,true)?round(array_sum($scores)/count($scores),1):null,'percent']];
   $taskRows=$tasks->map(fn($t)=>['id'=>$t->id,'source_type'=>'task','reference'=>'TSK-'.$t->id,'title'=>$t->title,'owner'=>$t->assignee?->name??'Unassigned','collaborators'=>collect($t->supporting_staff_ids??[])->map(fn($id)=>$names[$id]??'Retained staff history')->join(', '),'priority'=>$t->priority,'status'=>$t->isApprovedForPerformance()?'Completed · approved':$t->status,'due'=>$t->due_on?->toDateString(),'week'=>$t->created_at?->toDateString(),'url'=>route('portal.tasks.edit',$t),'can_edit'=>false]);
   $tables[]=$this->table('tasks','Task Tracker',[$col('reference','Task ID'),$col('title','Action'),$col('owner','Owner'),$col('collaborators','Collaborator'),$col('priority','Priority'),$col('status','Status'),$col('due','Due Date','date')],$taskRows,$v);
   $definitions=collect(config('department_kpis.brands_marketing',[]))->map(fn($d)=>['title'=>$d['name'],'definition'=>$d['definition'],'unit'=>$d['unit']==='GHS'?'GH₵':$d['unit'],'source'=>$d['source']]);
   $tables[]=$this->table('definitions','KPI Measurement Guide',[$col('title','KPI'),$col('definition','Measurement'),$col('unit','Unit'),$col('source','Evidence Source')],$definitions,['per_page'=>50,'sort'=>'title']);
   $notice='Hours use completed clock-in sessions and deduct the existing break allowance. Open sessions are not treated as completed workdays. Completion uses approved tasks. Productivity follows the existing 10% punctuality, 65% delivery and 25% KPI calculation; incomplete scores remain unmeasured.';
  }elseif($tab==='people'){
   $people=$rows->where('category','people')->map($flatten)->map(fn($r)=>array_merge($r,['cohort_label'=>config('brands_dashboard.schemas.people.cohort.options.'.$r['cohort'],$r['cohort']),'attrition_rate'=>!empty($r['average_headcount'])&&isset($r['attrition_count'])?round(100*$r['attrition_count']/$r['average_headcount'],1):null]));
   $tables[]=$this->table('people','People & Team Coverage',array_merge($base,[$col('cohort_label','Team'),$col('planned_count','Planned','number'),$col('active_count','Active','number'),$col('attrition_count','Attrition','number'),$col('attrition_rate','Attrition Rate','percent'),$col('leave_count','Leave','number'),$col('absent_count','Absent','number'),$col('notes','Updates','rich')]),$people,$v);
   $notice='Report Internal Staff, Unilever Merchandising, Off-Trade Merchandising and Activations & Campaigns separately. Attrition rate is departures divided by the recorded average headcount; a missing denominator remains unmeasured.';
  }elseif($tab==='perfect_store'){
   $partner=$v['partner']??'castel';$perfect=$rows->where('category','perfect_store')->filter(fn($r)=>($r['data']['partner']??null)===$partner);
   $metrics=$partner==='castel'?['coverage'=>'Coverage','osa'=>'OSA','innovation'=>'Innovation','perfect_store'=>'Perfect Store']:['coverage'=>'Coverage','osa'=>'OSA','must_have'=>'Must Have','npd'=>'NPD','perfect_store'=>'Perfect Store'];
   $previousRows=PerformanceRegister::whereIn('department',$aliases)->whereNotNull('approved_at')->whereIn('kind',['perfect_store','campaign'])->whereDate('period_start','>=',$from->copy()->subWeek())->whereDate('period_start','<=',$to)->orderByDesc('approved_at')->orderByDesc('id')->get()->map(fn($record)=>$reports->payload($record,'register'));
   $previousKey=fn($r,$week)=>$r['owner_id'].'|'.($r['data']['partner']??'').'|'.($r['data']['breakdown']??'overall').'|'.mb_strtolower(trim($r['data']['location']??'')).'|'.$week;
   $previousIndex=[];foreach($previousRows as $previous){$key=$previousKey($previous,Carbon::parse($previous['week'])->startOfWeek()->toDateString());if(!isset($previousIndex[$key]))$previousIndex[$key]=$previous['data'];}
   $metricRows=collect();foreach($perfect as $r)foreach($metrics as $key=>$label)if(collect(['target','previous','actual'])->contains(fn($p)=>isset($r['data'][$key.'_'.$p.'_percent']))){$data=$r['data'];$priorWeek=Carbon::parse($r['week'])->startOfWeek()->subWeek()->toDateString();$previous=$data[$key.'_previous_percent']??($previousIndex[$previousKey($r,$priorWeek)][$key.'_actual_percent']??null);$actual=$data[$key.'_actual_percent']??null;$metricRows->push($r+['metric'=>$label,'location'=>$data['location']??'Overall','breakdown'=>ucfirst($data['breakdown']??'overall'),'target'=>$data[$key.'_target_percent']??null,'previous'=>$previous,'actual'=>$actual,'change'=>$previous!==null&&$actual!==null?round($actual-$previous,1):null]);}
   $tables[]=$this->table('perfect','Perfect Store · '.ucfirst($partner),[$col('week','Reporting Week','date'),$col('owner','Owner'),$col('breakdown','Breakdown'),$col('location','Outlet / Region / Distributor'),$col('metric','KPI'),$col('target','Target','percent'),$col('previous','Previous Week','percent'),$col('actual','Current Week','percent'),$col('change','Change (pp)','number')],$metricRows,$v);
   $notice='Previous values use the saved comparison or the prior approved weekly report for the same owner, partner and location. Month and year views list weekly results. Percentages are not added or averaged across outlets, staff or weeks without a recorded denominator. Historical formatted KPI tables remain readable below.';
  }elseif($tab==='activation'){
   $activation=$rows->where('category','activation')->map($flatten);$briefs=$activation->filter(fn($r)=>!empty($r['brief_date']))->unique(fn($r)=>$r['owner_id'].'|'.$r['title'].'|'.($r['partner']??'').'|'.$r['brief_date']);$closed=$briefs->where('brief_status','closed');$decided=$closed->whereIn('outcome',['won','lost']);$won=$decided->where('outcome','won')->count();
   $summary=[['Briefs Received',$briefs->count(),'number'],['Responded',$briefs->whereNotNull('revert_date')->count(),'number'],['Pending',$briefs->whereIn('brief_status',['received','pending'])->count(),'number'],['Closed',$closed->count(),'number'],['Success Rate',$decided->count()?round(100*$won/$decided->count(),1):null,'percent']];
   $tables[]=$this->table('briefs','Briefs Tracker',array_merge([$col('id','ID')],$base,[$col('partner','Partner'),$col('client','Client / Requester'),$col('brief_date','Brief Date','date'),$col('revert_date','Revert Date','date'),$col('brief_status','Status'),$col('remarks','Remark','rich')]),$activation,$v);
   $kpis=$activation->map(fn($r)=>$r+['sales_achieved'=>!empty($r['target_sales'])&&isset($r['total_sales'])?round(100*$r['total_sales']/$r['target_sales'],1):null,'reach_achieved'=>!empty($r['target_reach'])&&isset($r['total_reach'])?round(100*$r['total_reach']/$r['target_reach'],1):null,'conversion_percent'=>!empty($r['conversion_base'])&&isset($r['conversions'])?round(100*$r['conversions']/$r['conversion_base'],1):null]);
   $tables[]=$this->table('activation_kpis','Activity KPIs',array_merge($base,[$col('partner','Partner'),$col('sales_unit','Sales Unit'),$col('target_sales','Target Sales','number'),$col('total_sales','Total Sales','number'),$col('sales_achieved','Sales Achieved','percent'),$col('target_reach','Target Reach','number'),$col('total_reach','Total Reach','number'),$col('reach_achieved','Reach Achieved','percent'),$col('conversion_percent','Conversion','percent'),$col('mechanic','Brief / Mechanic','rich')]),$kpis,$v);
   $notice='Success rate uses won briefs divided by closed briefs with a recorded won/lost outcome. Conversion uses the recorded eligible audience / interactions. Each result belongs to its reporting week; missing figures are not zero.';
  }elseif($tab==='visibility'){
   $visibility=$rows->where('category','visibility')->map($flatten)->map(fn($r)=>$r+['gap'=>isset($r['scheduled'],$r['deployed'])?$r['scheduled']-$r['deployed']:null]);
   $tables[]=$this->table('visibility','Visibility Tracker',array_merge($base,[$col('posm_type','POSM Type'),$col('partner','Partner'),$col('planned_scope','Planned Scope','number'),$col('active_scope','Active Scope','number'),$col('scheduled','Total Scheduled','number'),$col('deployed','Total Deployed','number'),$col('gap','Gap to Go','number'),$col('status','Status'),$col('notes','Update','rich')]),$visibility,$v);
   $movements=\App\Models\PosmLedger::with('creator')->whereRaw('COALESCE(occurred_on, DATE(created_at)) BETWEEN ? AND ?',[$from->toDateString(),$to->toDateString()])->when($owner,fn($q)=>$q->where('created_by',$owner))->get()->map(fn($m)=>['id'=>$m->id,'week'=>$m->occurred_on?->toDateString()??$m->created_at->toDateString(),'title'=>$m->item_name,'owner'=>$m->creator?->name??'Retained staff history','partner'=>$m->client_brand,'quantity_in'=>$m->quantity_in,'quantity_out'=>$m->quantity_out,'status'=>'Recorded movement']);
   $tables[]=$this->table('movements','POSM Movements',array_merge($base,[$col('partner','Client / Brand'),$col('quantity_in','Quantity In','number'),$col('quantity_out','Quantity Out','number'),$col('status','Status')]),$movements,$v);
   $notice='Gap to Go is scheduled quantity minus deployed quantity. This reporting view does not change warehouse stock balances.';
  }else{
   $work=$rows->where('category','workstream')->map($flatten)->map(fn($r)=>array_replace($r,['collaborator_names'=>collect($r['collaborators']??[])->map(fn($id)=>($names[$id]??'Retained staff history').(!empty($r['collaborator_roles'][$id])?' · '.$r['collaborator_roles'][$id]:''))->join(', ')]));
   $latest=$work->sortByDesc('week')->unique(fn($r)=>$weekly->firstWhere('id',$r['id'])?->report_series??'entry-'.$r['id']);
   $summary=[['Total Tasks',$latest->count(),'number'],['Tasks Pending',$latest->where('status','!=','Done')->count(),'number'],['Tasks Completed',$latest->where('status','Done')->count(),'number']];
   $tables[]=$this->table('workstream','Task Tracker',[$col('week','Week','date'),$col('project','Project / Workstream'),$col('brand','Brand'),$col('title','Task'),$col('task_in_week','Task in Week','rich'),$col('owner','Owner'),$col('collaborator_names','Collaborators'),$col('priority','Priority'),$col('status','Status'),$col('kpis','KPI Commitments','rich')],$work,$v);
   $notice='Weekly reports retain their original reporting dates. Month and year views list the saved weekly entries. Totals use the latest status per linked workstream; reported completion remains separate from verified productivity.';
  }
  if(in_array($tab,['people','perfect_store','activation','visibility'])){
   $pattern=match($tab){'people'=>'/people|resource|capability|welfare|training|staff|compensation/i','perfect_store'=>'/perfect\s*store|OSA|merchandis|coverage|shelf|retail/i','activation'=>'/activation|campaign|promotion|back.to.school|vaseline|heineken/i','visibility'=>'/visibility|POSM|branding|shelf|deployment|installation/i'};
   $saved=$rows->where('source_type','weekly')->filter(fn($r)=>preg_match($pattern,strip_tags($r['title'].' '.json_encode($r['data']))))->map(fn($r)=>$r+['project'=>$r['data']['project'],'task_in_week'=>$r['data']['task_in_week'],'kpis'=>$r['data']['kpis']??null]);
   $tables[]=$this->table('saved_reports','Earlier Saved Reports',array_merge($base,[$col('project','Workstream'),$col('task_in_week','Reported Progress','rich'),$col('kpis','KPI Commitments','rich')]),$saved,$v);
  }
  return ['tab'=>$tab,'period'=>['mode'=>$period,'from'=>$from->toDateString(),'to'=>$to->toDateString()],'partner'=>$v['partner']??'castel','staff'=>$staff->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'active'=>$u->isActive(),'photo'=>$u->profilePhotoUrl()]),'tables'=>$tables,'summary'=>$summary,'notice'=>$notice,'can_enter'=>BrandsReports::member($actor),'can_review'=>BrandsReports::manager($actor),'actor'=>$actor->id];
 }
 private function table(string $id,string $title,array $columns,Collection $rows,array $filters):array {
  $sort=$filters['sort']??'newest';$rows=match($sort){'title'=>$rows->sortBy('title',SORT_NATURAL|SORT_FLAG_CASE),'owner'=>$rows->sortBy('owner',SORT_NATURAL|SORT_FLAG_CASE),'oldest'=>$rows->sortBy('week'),default=>$rows->sortByDesc(fn($r)=>($r['week']??'').'-'.str_pad((string)($r['id']??0),12,'0',STR_PAD_LEFT))};$per=$filters['per_page']??10;$total=$rows->count();$last=max(1,(int)ceil($total/$per));$page=min((int)($filters['page']??1),$last);
  return ['id'=>$id,'title'=>$title,'columns'=>$columns,'rows'=>$rows->slice(($page-1)*$per,$per)->map(function($row)use($columns){foreach($columns as $column)if($column['format']==='rich')$row[$column['key']]=\App\Support\ReportRichText::html($row[$column['key']]??'');unset($row['data']);return $row;})->values(),'total'=>$total,'page'=>$page,'last'=>$last];
 }
}
